"use client";

/* AI BRIEFING — the DeepSeek macro analysis card at the top of the
 * dashboard. Reads GET /api/briefing (latest stored row, generated by
 * the 09:15 ET pre-open cron, the nightly post-close step, or the
 * refresh button here). DISPLAY-ONLY context — never imported by
 * signal code. */

import { useCallback, useEffect, useRef, useState } from "react";
import { BentoCard, TintChip } from "./BentoCard";
import { adminFetch } from "@/lib/adminFetch";
import type { BriefingRow } from "@/lib/macroBriefing";
import type { BentoTone } from "./BentoCard";
import { chartLinesOfSnapshot, type ChartLine } from "@/lib/briefingText";

type Load = { row: BriefingRow | null; error: string | null; cooldownMs: number };

const POLL_MS = 60_000;
const FAST_POLL_MS = 5_000;
const REFRESH_TIMEOUT_MS = 20_000;

function biasTone(bias: string): BentoTone {
  if (bias === "up") return "long";
  if (bias === "down") return "short";
  return "warn";
}

function volTone(vol: string): BentoTone {
  if (vol === "extreme" || vol === "elevated") return "warn";
  if (vol === "compressed") return "info";
  return "muted";
}

/** ISO → "MM-DD HH:MM" New York (the dashboard's wall clock) */
function etStamp(iso: string): string {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return iso;
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour12: false,
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).formatToParts(new Date(t));
  const g: Record<string, string> = {};
  for (const p of parts) g[p.type] = p.value;
  return `${g.month}-${g.day} ${g.hour}:${g.minute} ET`;
}

export default function AiBriefingCard({ onChartLines }: { onChartLines?: (lines: ChartLine[]) => void }) {
  const [load, setLoad] = useState<Load>({ row: null, error: null, cooldownMs: 0 });
  const [refreshing, setRefreshing] = useState(false);
  const [fast, setFast] = useState(false);
  const seenGenAt = useRef<string | null>(null);

  const fetchRow = useCallback(async () => {
    try {
      const r = await fetch("/api/briefing");
      const j = (await r.json()) as { ok?: boolean; briefing: BriefingRow | null; cooldownRemainingMs?: number };
      const row = j.briefing ?? null;
      if (fast && row && seenGenAt.current && row.generated_at !== seenGenAt.current) {
        setFast(false); // the refresh landed — back to the slow poll
      }
      seenGenAt.current = row?.generated_at ?? null;
      setLoad({ row, error: null, cooldownMs: j.cooldownRemainingMs ?? 0 });
    } catch (e) {
      setLoad((cur) => ({ ...cur, error: e instanceof Error ? e.message : String(e) }));
    }
  }, [fast]);

  useEffect(() => {
    fetchRow();
    const id = setInterval(fetchRow, fast ? FAST_POLL_MS : POLL_MS);
    return () => clearInterval(id);
  }, [fetchRow, fast]);

  // hand the briefing's level lines up to the page (they mark the chart)
  useEffect(() => {
    onChartLines?.(chartLinesOfSnapshot(load.row?.snapshot ?? null));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [load.row]);

  const refresh = async () => {
    if (refreshing) return;
    setRefreshing(true);
    setFast(true);
    try {
      // the generation can take minutes on a cold macro cache (earnings
      // scan); don't block on it — the fast poll above picks the new row
      // up as soon as it lands.
      const r = await adminFetch("/api/briefing", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "refresh" }),
        signal: AbortSignal.timeout(REFRESH_TIMEOUT_MS),
      });
      const j = (await r.json()) as { ok?: boolean; briefing: BriefingRow | null; cooldown?: boolean; cooldownRemainingMs?: number };
      if (j.briefing) {
        seenGenAt.current = j.briefing.generated_at;
        setLoad({ row: j.briefing, error: null, cooldownMs: j.cooldownRemainingMs ?? 0 });
        setFast(false);
      } else if (j.cooldown) {
        setLoad((cur) => ({ ...cur, cooldownMs: j.cooldownRemainingMs ?? 0 }));
        setFast(false);
      }
    } catch {
      /* the poll will surface whatever landed */
    } finally {
      setRefreshing(false);
    }
  };

  const row = load.row;
  const cooldownLabel = load.cooldownMs > 0 ? `cool ${Math.ceil(load.cooldownMs / 60_000)}m` : null;
  const badge = row ? (
    <span className="flex items-center gap-1.5 font-mono text-[10px] text-zinc-500">
      {row.source === "llm" ? "DeepSeek" : "deterministic"} · {etStamp(row.generated_at)}
    </span>
  ) : null;

  return (
    <BentoCard kicker="AI macro briefing" tone="info" hero badge={badge} title={undefined}>
      {row ? (
        <>
          {/* the bottom line — rendered here (not as the BentoCard title, which truncates) */}
          <p className="mb-1.5 text-[15px] font-semibold leading-snug tracking-tight text-zinc-50">{row.headline}</p>

          <div className="mb-2 flex flex-wrap items-center gap-1">
            <TintChip label="bias" value={row.bias.toUpperCase()} tone={biasTone(row.bias)} />
            <TintChip label="vol" value={row.vol} tone={volTone(row.vol)} />
            {row.model && <TintChip label="model" value={row.model} tone="muted" />}
          </div>

          {row.read.length > 0 && (
            <div className="mb-2 space-y-0.5">
              {row.read.slice(0, 2).map((d, i) => (
                <div key={i} className="font-mono text-[11px] leading-snug text-zinc-300">
                  <span className="text-zinc-600">why </span>{d}
                </div>
              ))}
            </div>
          )}

          {row.levels.length > 0 && (
            <div className="mb-2 flex flex-wrap gap-x-4 gap-y-1 rounded-lg border border-zinc-800/70 bg-zinc-900/40 px-2.5 py-2">
              {row.levels.slice(0, 4).map((l, i) => (
                <span key={i} className="font-mono text-[10px] text-zinc-400">
                  <span className="uppercase tracking-wider text-zinc-600">{l.label}</span>{" "}
                  <span className="text-[11px] font-semibold text-zinc-100">{l.value}</span>
                  {l.note && <span className="text-zinc-500"> · {l.note}</span>}
                </span>
              ))}
            </div>
          )}

          {row.watchFors.length > 0 && (
            <div className="mb-1.5 space-y-0.5">
              {row.watchFors.slice(0, 3).map((w, i) => (
                <div key={i} className="font-mono text-[11px] leading-snug text-zinc-300">
                  <span className="text-info">◉ </span>{w}
                </div>
              ))}
            </div>
          )}

          {row.caveats.length > 0 && (
            <p className="mb-2 font-mono text-[9px] leading-snug text-zinc-500">
              {row.caveats.slice(0, 2).join(" · ")}
            </p>
          )}

          <div className="flex flex-wrap items-center justify-between gap-2 border-t border-zinc-800/70 pt-1.5">
            <span className="font-mono text-[9px] text-zinc-600">{row.kind} · display-only, not a signal</span>
            <button
              onClick={refresh}
              disabled={refreshing}
              className={`rounded border px-2 py-0.5 font-mono text-[10px] ${
                refreshing ? "border-zinc-700 text-zinc-500" : "border-info/40 bg-info/10 text-info hover:border-info/70"
              }`}
            >
              {refreshing ? "regenerating…" : cooldownLabel ? `refresh (${cooldownLabel})` : "refresh now"}
            </button>
          </div>
        </>
      ) : (
        <p className="font-mono text-xs text-zinc-600">
          {load.error
            ? `briefing unavailable — ${load.error}`
            : "no briefing yet — the first pre-open run lands at 09:15 ET, or press refresh"}
        </p>
      )}
    </BentoCard>
  );
}
